def update_service_case_status(case_id=None, status=None, note=None, expected_completion_date=None):
    if not case_id:
        frappe.throw("case_id is required")

    _require_service_case_update_scope(case_id)

    if not status:
        frappe.throw("status is required")

    allowed_statuses = [
        "Open",
        "In Progress",
        "Waiting for Customer",
        "Waiting for Payment",
        "Completed",
        "Cancelled",
    ]

    if status not in allowed_statuses:
        frappe.throw("Invalid status")

    if not frappe.db.exists("OMC Service Request", case_id):
        frappe.throw("Service case not found", frappe.DoesNotExistError)

    doc = frappe.get_doc("OMC Service Request", case_id)
    old_status = doc.status or ""

    if status == "Completed":
        from omc_app.api import workflow_automation

        blockers = workflow_automation.completion_blockers(doc)
        if blockers:
            frappe.throw(
                "Cannot complete this service request: " + " ".join(blockers),
                frappe.ValidationError,
            )

    doc.status = status

    if expected_completion_date is not None:
        doc.expected_completion_date = expected_completion_date or None

    if status in ["Completed", "Cancelled"] and not doc.closed_on:
        doc.closed_on = frappe.utils.now_datetime()

    if status not in ["Completed", "Cancelled"]:
        doc.closed_on = None

    doc.save(ignore_permissions=True)

    if old_status != status:
        description = note or f"Status changed from {old_status or 'Unknown'} to {status}."

        if status == "Completed":
            from omc_app.api import workflow_automation

            workflow_automation.finalize_completed_case(doc)

        _create_service_timeline_entry(
            service_request=doc.name,
            event_type="Status Updated",
            title=f"Status Updated: {status}",
            description=description,
            visible_to_customer=1,
        )
    elif note:
        _create_service_timeline_entry(
            service_request=doc.name,
            event_type="Update",
            title="Case Updated",
            description=note,
            visible_to_customer=1,
        )

    if old_status != status:
        status_messages = {
            "Open": "Your service request is open and awaiting review.",
            "In Progress": "OMC has started working on your service request.",
            "Waiting for Customer": (
                "OMC needs information or action from you. "
                "Open the request to review the next step."
            ),
            "Waiting for Payment": (
                "A payment step is pending for your service request."
            ),
            "Completed": "Your service request has been completed.",
            "Cancelled": "Your service request has been cancelled.",
        }
        _create_service_notification(
            doc,
            title=f"Service status: {status}",
            message=note or status_messages.get(
                status,
                f"Your service request status changed to {status}.",
            ),
            notification_type="Service Update",
        )

    frappe.db.commit()

    return {
        "name": doc.name,
        "status": doc.status,
        "updated": True,
        "message": "Service case updated.",
    }

_can_customer_cancel_service_case.source:
def _can_customer_cancel_service_case(case_id, status=None):
    if not case_id:
        return False
    normalized_status = (status or "").strip().lower()
    if normalized_status not in {"open", "waiting for customer", "waiting for documents"}:
        return False
    if frappe.db.exists("OMC Service Document", {"service_request": case_id, "attachment": ["!=", ""]}):
        return False
    if frappe.db.exists("OMC Service Payment", {"service_request": case_id}):
        return False
    return True

cancel_service_request.source:
def cancel_service_request(case_id=None, name=None, service_request=None, request_id=None, reason=None):
    resolved_case_id = case_id or name or service_request or request_id
    if not resolved_case_id:
        frappe.throw("Service request reference is required.")

    request = frappe.get_doc("OMC Service Request", resolved_case_id)
    user = frappe.session.user
    can_access_internal_workspace = mobile._can_access_internal_workspace()
    customer_profile = (
        None
        if can_access_internal_workspace
        else mobile.get_current_customer_profile()
    )
    owns_request = bool(
        customer_profile
        and getattr(request, "customer_profile", None) == customer_profile.name
    )

    if user != "Administrator" and not owns_request:
        frappe.throw(
            "Only the owning customer can cancel this service request.",
            frappe.PermissionError,
        )

    if not _can_customer_cancel_service_case(request.name, request.status):
        frappe.throw("This request can no longer be cancelled from the app. Please contact OMC support.")

    request.status = "Cancelled"
    request.closed_on = frappe.utils.now_datetime()
    request.add_comment("Comment", reason or "Service request cancelled by customer from mobile app.")
    request.save(ignore_permissions=True)
    frappe.db.commit()

    return {"service_request": request.name, "status": request.status, "message": "Service request cancelled successfully.", "can_cancel": False}

