def sync_task_status(doc, method=None) -> dict[str, Any]:
    task_name = _text(getattr(doc, "name", None))
    if not task_name:
        return {"updated": False, "reason": "missing task name"}

    request_name = frappe.db.get_value(
        "OMC Service Request",
        {"erp_task": task_name},
        "name",
    )
    if not request_name:
        return {"updated": False, "reason": "task is not linked to an OMC request"}

    raw_status = _text(getattr(doc, "status", None))
    operation_status = _text(getattr(doc, "custom_operation_status", None))
    mapped_status = customer_status(raw_status, operation_status)

    request_values = {"status": mapped_status}
    if mapped_status in {"Completed", "Cancelled"}:
        request_values["closed_on"] = frappe.utils.now_datetime()
    else:
        request_values["closed_on"] = None

    frappe.db.set_value(
        "OMC Service Request",
        request_name,
        request_values,
        update_modified=True,
    )

    erp_service = frappe.db.get_value(
        "OMC Service Request",
        request_name,
        "erp_service",
    )
    service_status = _service_status_value(mapped_status, raw_status)
    if erp_service and service_status and frappe.db.exists("Service", erp_service):
        frappe.db.set_value(
            "Service",
            erp_service,
            "status",
            service_status,
            update_modified=True,
        )

    return {
        "updated": True,
        "request": request_name,
        "erp_service": erp_service or "",
        "task_status": raw_status,
        "operation_status": operation_status,
        "customer_status": mapped_status,
        "service_status": service_status or "",
    }

_set_request_state.source:
def _set_request_state(request, *, status: str, customer="", service="", task="", error="") -> None:
    values = {
        "erp_sync_status": status,
        "erp_customer": customer or None,
        "erp_service": service or None,
        "erp_task": task or None,
        "erp_sync_error": error[:1000] if error else None,
    }
    for fieldname, value in values.items():
        if request.meta.get_field(fieldname):
            request.set(fieldname, value)
            frappe.db.set_value(
                request.doctype,
                request.name,
                fieldname,
                value,
                update_modified=False,
            )

