import frappe
from frappe.model.document import Document


class OMCServiceRequest(Document):
	def before_insert(self):
		if not self.naming_series:
			self.naming_series = "OMC-SR-.YYYY.-.#####"

		if not self.requested_by:
			self.requested_by = frappe.session.user

	def before_save(self):
		if self.service and not self.service_title:
			self.service_title = frappe.db.get_value("OMC Service", self.service, "title") or self.service

		if self.customer_profile and not self.customer_name:
			self.customer_name = frappe.db.get_value("OMC Customer Profile", self.customer_profile, "full_name") or ""

		if self._entered_terminal_status():
			try:
				from omc_app.api.customer_documents import archive_service_documents_for_status

				archive_service_documents_for_status(self.name, self.status)
			except Exception:
				frappe.log_error(
					frappe.get_traceback(),
					"OMC Service Document Auto Archive Failed",
				)

	def _entered_terminal_status(self):
		if self.status not in {"Completed", "Cancelled"}:
			return False

		previous = self.get_doc_before_save()
		return previous is None or previous.status != self.status

from types import SimpleNamespace
from unittest import TestCase
from unittest.mock import patch

from omc_app.api import workflow_automation


class TestWorkflowCompletion(TestCase):
    def _case(self):
        return SimpleNamespace(
            name="OMC-SR-TEST",
            title="Test Service",
            service="TEST-SERVICE",
            customer_profile="OMC-CUST-TEST",
        )

    @patch.object(workflow_automation.mobile, "_service_required_documents")
    @patch.object(workflow_automation.frappe, "get_all")
    @patch.object(workflow_automation.frappe.db, "count")
    def test_completion_blocked_by_unpaid_payment(
        self,
        count,
        get_all,
        required_documents,
    ):
        required_documents.return_value = []
        get_all.side_effect = [
            [SimpleNamespace(status="Pending")],
        ]
        count.side_effect = [0, 0]

        blockers = workflow_automation.completion_blockers(self._case())

        self.assertIn("Required payment has not been confirmed.", blockers)

    @patch.object(workflow_automation.mobile, "_service_required_documents")
    @patch.object(workflow_automation.frappe, "get_all")
    @patch.object(workflow_automation.frappe.db, "count")
    def test_paid_case_has_no_payment_blocker(
        self,
        count,
        get_all,
        required_documents,
    ):
        required_documents.return_value = []
        get_all.side_effect = [
            [SimpleNamespace(status="Paid")],
        ]
        count.side_effect = [0, 0]

        blockers = workflow_automation.completion_blockers(self._case())

        self.assertNotIn("Required payment has not been confirmed.", blockers)

    @patch.object(workflow_automation.mobile, "_create_customer_notification")
    @patch.object(workflow_automation.mobile, "_create_service_timeline_entry")
    @patch.object(workflow_automation.frappe.db, "set_value")
    def test_completion_closes_todos_and_notifies_customer(
        self,
        set_value,
        timeline,
        notification,
    ):
        workflow_automation.finalize_completed_case(self._case())

        set_value.assert_called_once()
        timeline.assert_called_once()
        notification.assert_called_once()

    @patch.object(workflow_automation.mobile, "_create_customer_notification")
    @patch.object(workflow_automation, "_notification_exists")
    def test_notify_once_prevents_duplicate(self, exists, create_notification):
        exists.return_value = True

        result = workflow_automation._notify_once(
            title="Reminder",
            message="Test",
            notification_type="Reminder",
            reference_doctype="OMC Service Request",
            reference_name="OMC-SR-TEST",
            customer_profile="OMC-CUST-TEST",
        )

        self.assertIsNone(result)
        create_notification.assert_not_called()
